content:
Below is a clean Terraform layout that creates:

- **S3 bucket** with:
  - versioning
  - server-side encryption
  - public access blocked
- **RDS PostgreSQL** with:
  - deletion protection
  - backup retention
  - not publicly accessible
- **IAM role for service accounts**
  - supports **OIDC trust** for Kubernetes service accounts
  - least-privilege S3 access

It supports **dev/prod** using either:

- `*.tfvars` files, or
- Terraform workspaces

---

# Suggested structure

```text
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3_bucket/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds_postgres/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam_service_account_role/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

# Root module

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

---

## `variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
}

variable "environment" {
  description = "Environment name: dev or prod"
  type        = string
}

variable "project_name" {
  description = "Project/application name"
  type        = string
}

variable "bucket_name" {
  description = "S3 bucket name"
  type        = string
}

variable "enable_bucket_replication" {
  description = "Enable cross-region replication for prod if needed"
  type        = bool
  default     = false
}

variable "db_name" {
  description = "PostgreSQL database name"
  type        = string
}

variable "db_username" {
  description = "PostgreSQL master username"
  type        = string
}

variable "db_password" {
  description = "PostgreSQL master password"
  type        = string
  sensitive   = true
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_allocated_storage" {
  description = "RDS allocated storage in GB"
  type        = number
}

variable "db_multi_az" {
  description = "Enable Multi-AZ for RDS"
  type        = bool
}

variable "db_storage_encrypted" {
  description = "Enable encryption at rest for RDS"
  type        = bool
  default     = true
}

variable "db_backup_retention_period" {
  description = "RDS backup retention days"
  type        = number
  default     = 7
}

variable "vpc_security_group_ids" {
  description = "Security groups for RDS"
  type        = list(string)
}

variable "db_subnet_ids" {
  description = "Subnet IDs for RDS subnet group"
  type        = list(string)
}

variable "oidc_provider_arn" {
  description = "OIDC provider ARN for EKS IRSA"
  type        = string
}

variable "oidc_provider_url" {
  description = "OIDC provider URL for EKS IRSA, without https://"
  type        = string
}

variable "k8s_namespace" {
  description = "Kubernetes namespace for service account"
  type        = string
}

variable "k8s_service_account_name" {
  description = "Kubernetes service account name"
  type        = string
}
```

---

## `main.tf`

```hcl
provider "aws" {
  region = var.aws_region
}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

module "s3_bucket" {
  source = "./modules/s3_bucket"

  bucket_name                = var.bucket_name
  enable_versioning          = true
  enable_encryption          = true
  enable_replication         = var.enable_bucket_replication
  replication_destination_region = "us-west-2"
  tags                       = local.common_tags
}

module "rds_postgres" {
  source = "./modules/rds_postgres"

  identifier                = "${var.project_name}-${var.environment}-postgres"
  db_name                   = var.db_name
  username                  = var.db_username
  password                  = var.db_password
  instance_class            = var.db_instance_class
  allocated_storage         = var.db_allocated_storage
  multi_az                  = var.db_multi_az
  storage_encrypted         = var.db_storage_encrypted
  backup_retention_period   = var.db_backup_retention_period
  deletion_protection       = true
  publicly_accessible       = false
  vpc_security_group_ids    = var.vpc_security_group_ids
  subnet_ids                = var.db_subnet_ids
  tags                      = local.common_tags
}

module "iam_service_account_role" {
  source = "./modules/iam_service_account_role"

  role_name                 = "${var.project_name}-${var.environment}-sa-role"
  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  k8s_namespace             = var.k8s_namespace
  k8s_service_account_name  = var.k8s_service_account_name
  s3_bucket_arn             = module.s3_bucket.bucket_arn
  tags                      = local.common_tags
}
```

---

## `outputs.tf`

```hcl
output "bucket_name" {
  value = module.s3_bucket.bucket_name
}

output "bucket_arn" {
  value = module.s3_bucket.bucket_arn
}

output "rds_endpoint" {
  value = module.rds_postgres.endpoint
}

output "rds_instance_id" {
  value = module.rds_postgres.instance_id
}

output "iam_role_arn" {
  value = module.iam_service_account_role.role_arn
}
```

---

# S3 module

## `modules/s3_bucket/variables.tf`

```hcl
variable "bucket_name" {
  type = string
}

variable "enable_versioning" {
  type    = bool
  default = true
}

variable "enable_encryption" {
  type    = bool
  default = true
}

variable "enable_replication" {
  type    = bool
  default = false
}

variable "replication_destination_region" {
  type    = string
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

---

## `modules/s3_bucket/main.tf`

```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.enable_encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
```

> If you want KMS instead of AES256, you can replace the SSE block with KMS settings.

---

## `modules/s3_bucket/outputs.tf`

```hcl
output "bucket_name" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}
```

